window.docContents[98].resolve({"/LindenstraussPolynomials/Limit/#mod-doc-LindenstraussPolynomials___Limit-1-0":{"contents":"The limit polynomial\n\nThe perturbations are summable: \\|P_m-P_k\\|\\le 2\\alpha_k/(1-a), so (P_k) converges to a symmetric form Q with \\|Q-P_k\\|\\le4\\alpha_k (eq:tailQ).\n\n\n","context":"","header":"LindenstraussPolynomials.Limit","id":"/LindenstraussPolynomials/Limit/#mod-doc-LindenstraussPolynomials___Limit-1-0"}});